body.userscript:





            // 인감구분 변경시 현재구분과 비교하기 위해 사용, 이전 클릭되어 있던 인감구분을 저장

            //폼, smr_number등의 정보를 담는 변수



            //그리드 데이터의 정보를 담는 변수







            //새로 만든 요청이라면 Y








            switch (name) {
                case "SAVE":
                    doSave();
                    break;
                case "APPROVAL_REQ":
                    doApprovalRequest();
                    break;
                case "MANAGER_REQUEST":
                    doManagerRequest();
                    break;
                case "MANAGER_ACCEPT":
                    doManagerAccept();
                    break;
                case "MANAGER_REJECT":
                    doManagerReject();
                    break;
                case "COMPLETE":
                    doComplete();
                    break;
                case "BACK":
                    doBack();
                    break;
                default:
                    break;
            }




            // 채번 따서 $reqSealInfo에 채번넣고 기본셋팅
            $documentList = new Object(); //문서정보리스트

            gridObj2_title.innerHTML = Sepoa.cache.text.get('SLM_211.GRID_1_TITLE');
            gridObj2_title.setAttribute('style', 'font-size:14px;padding-top: 15px;');
            formObj.setValue('APPLY_TYPE', 'D');

            if (sUtils.ux.getRootScreenID() == 'SLM_250') {
                if (!Sepoa.request.SMR_NUMBER) {
                    isNew = true;
                    var smrNumber = getDocumentNumber("SMR"); //채번
                } else {
                    isNew = false;
                    var smrNumber = Sepoa.request.SMR_NUMBER;
                }
                $reqSealInfo.SMR_NUMBER = smrNumber;
                formObj.setValue('SMR_NUMBER', smrNumber);

                initBtn();
            }




            btnObj.forEachBtn(function(btnId) {
                if (btnId) {
                    btnObj.showButton(btnId, false);
                }
            });
            gridObj2_btnObj.forEachBtn(function(btnId) {
                if (btnId) {
                    gridObj2_btnObj.showButton(btnId, false);
                }
            });
            gridObj2.setColumnHidden(gridObj2.getColIndexById('ATTACH_IMG'), 1);




            document.getElementById('cREwYmeIzYyYmeQRSg').style.display = 'inline-block';




            // 처음에 모든 버튼을 숨기고 상황에 맞는 버튼 표출
            hideAllButtons();

            if (SCREEN_MODE == 'APP') {
                gridObj2.setReadOnly(true);
                showButtonArea();
            } else if (['', Sepoa.info.ID].indexOf(formObj.getValue('ADD_USER_ID')) > -1 && (smrStatus == 'T' || (SCREEN_MODE == 'MY_REQ' && VIEW_MODE == 'EDITOR'))) { //임시저장 또는 요청내역에서 수정하는 경우
                VIEW_MODE == 'EDITOR';
                gridObj2.setReadOnly(false);
                gridObj2.setColumnHidden(gridObj2.getColIndexById('SELECTED'), 0);

                if (moveFlag == 'N') { //기존 임시저장일 경우 N, Y는 요청내역에서 들어올 시 doquery에서 Y을 들고 들어옴 
                    btnObj.showButton('back', true);
                }

                // 임시저장 상태일 때 다음 모듈에 따라 표출될 버튼이 다름
                // PARENT: 어느 페이지 안에서 서비스를 실행하는지 확인
                doServiceAjax('sepoa.svc.seal.SepoaReqSealService', 'CONNECTION', 'doSelectNextModule', {
                    ALIAS: 'CREATE',
                    PARENT: 'USW'
                }, function(so) {
                    if (so.status == 1) {
                        var moduleArr = JSON.parse(so.result[0]);
                        var nextModule = moduleArr.MODULE;

                        gridObj2_btnObj.showButton('rowadd_1,rowdelete_1', true);

                        switch (nextModule) {
                            case "USW1635987860041":
                                // 결재
                                btnObj.showButton('save,approval_req', true);
                                break;
                            case "USW1635987861018":
                                // 완료
                                btnObj.showButton('save,complete', true);
                                break;
                            default:
                                break;
                        }
                        showButtonArea();
                    } else {
                        Alert(Sepoa.cache.text.get("MESSAGE.1002"));
                    }
                });

            } else if (smrStatus != 'T' || ['', Sepoa.info.ID].indexOf(formObj.getValue('ADD_USER_ID')) == -1) {
                var alias = '';
                formObj.setViewMode(true);
                formObj.setdisable('SEAL_USE_TYPE_IMG', true);
                gridObj2.setReadOnly(true);
                gridObj2.setColumnHidden(gridObj2.getColIndexById('SELECTED'), 1);

                if (smrStatus == 'C') {
                    gridObj2.setColumnHidden(gridObj2.getColIndexById('ATTACH_IMG'), 0);
                }

                if (Sepoa.request.SMR_NUMBER || ['APPR_TURN', 'APPR_DONE'].indexOf(SCREEN_MODE) > -1) {
                    btnObj.showButton('back', false);
                } else {
                    btnObj.showButton('back', true);
                }

                showButtonArea();
            }




            if (mode) SCREEN_MODE = mode;




            $documentList = {};
            $reqSealInfo = {};
            formObj.clear();
            gridObj2.clearAll();
            moveFlag = move;
            VIEW_MODE = viewMode || '';
            isNew = false;

            if (smrNumber) {
                $reqSealInfo.SMR_NUMBER = smrNumber;
                formObj.setValue('SMR_NUMBER', smrNumber);
            }

            doServiceAjax('sepoa.svc.seal.SepoaReqSealService', 'CONNECTION', 'doSelectRequestInfo', { // 날인요청의 정보를 조회
                SMR_NUMBER: smrNumber,
                APPLY_TYPE: 'D'
            }, function(so) {
                if (so.status == 1) {
                    var reqData = JSON.parse(so.result[0]);
                    var documentList = reqData[0].DOCUMENT_LIST; //서류문서
                    var reqSealInfo = reqData[0].REQ_SEAL_INFO; //객체정보
                    var attachList = reqData[0].ATTACH_DOCUMENT_LIST;
                    var btnFlag = false;
                    formObj.dataMapper(reqSealInfo, 'JSON');
                    $reqSealInfo.SMR_NUMBER = reqSealInfo.SMR_NUMBER;
                    smrStatus = reqSealInfo.SMR_STATUS;

                    if (smrStatus == 'T' && ['', Sepoa.info.ID].indexOf(reqSealInfo.ADD_USER_ID) > -1) {
                        VIEW_MODE = 'EDITOR';
                    }
                    var attachDocArr = new Array();
                    for (var i in attachList) {
                        var maxRowId = dhx4.newId();
                        var attachDocData = {};
                        gridObj2.addRow(maxRowId, '', gridObj2.getRowsNum());
                        gridObj2.cells(maxRowId, gridObj2.getColIndexById('SMI_SEQ_TEMP')).setValue('temp_' + maxRowId);
                        gridObj2.cells(maxRowId, gridObj2.getColIndexById('SD_NUMBER')).setValue(attachList[i].SD_NUMBER);
                        gridObj2.cells(maxRowId, gridObj2.getColIndexById('SMI_NUMBER')).setValue(attachList[i].SMI_NUMBER);
                        gridObj2.cells(maxRowId, gridObj2.getColIndexById('COUNT')).setValue(attachList[i].COUNT);
                        gridObj2.cells(maxRowId, gridObj2.getColIndexById('REAL_DOC_CHK')).setValue(attachList[i].REAL_DOC_CHK);
                        gridObj2.cells(maxRowId, gridObj2.getColIndexById('CONTENTS')).setValue(attachList[i].CONTENTS);
                        gridObj2.cells(maxRowId, gridObj2.getColIndexById('ATTACH_NO')).setValue(attachList[i].ATTACH_NO);
                        gridObj2.cells(maxRowId, gridObj2.getColIndexById('ATTACH_SEQ')).setValue(attachList[i].ATTACH_SEQ);

                        searchSRAD(maxRowId, attachList[i].SMI_NUMBER);

                        if (gridObj2.cells(maxRowId, gridObj2.getColIndexById('ATTACH_NO')).getValue() != '' &&
                            gridObj2.cells(maxRowId, gridObj2.getColIndexById('ATTACH_SEQ')).getValue() != '') {
                            gridObj2.cells(maxRowId, gridObj2.getColIndexById('ATTACH_IMG')).setIcon('ATTACH_IMG2');
                            gridObj2.cells(maxRowId, gridObj2.getColIndexById('ATTACH_IMG')).cell.children[0].style = 'filter:none';
                        }

                        if (gridObj2.cells(maxRowId, gridObj2.getColIndexById('REAL_DOC_CHK')).getValue() == '1') {
                            gridObj2.cells(maxRowId, gridObj2.getColIndexById('ATTACH_IMG')).setIcon('ATTACH_IMG');
                            gridObj2.cells(maxRowId, gridObj2.getColIndexById('ATTACH_IMG')).cell.children[0].style = 'filter:none';
                        }

                        if (attachList[i].ATTACH_CNT >= gridObj2.cells(maxRowId, gridObj2.getColIndexById('COUNT')).getValue()) {
                            gridObj2.cells(maxRowId, gridObj2.getColIndexById('ATTACH_IMG')).setIcon('ATTACH_IMG2');
                            gridObj2.cells(maxRowId, gridObj2.getColIndexById('ATTACH_IMG')).cell.children[0].style = 'filter:none';
                        }
                        gridObj2.showRow(maxRowId);

                        attachDocData.SD_NUMBER = attachList[i].SD_NUMBER;
                        attachDocData.SMI_NUMBER = attachList[i].SMI_NUMBER;
                        attachDocData.DOC_TYPE = attachList[i].DOC_TYPE;
                        attachDocData.COUNT = String(attachList[i].COUNT);
                        attachDocData.CONTENTS = attachList[i].CONTENTS;

                        attachDocArr.push(attachDocData);
                    }

                    $attachDocumentList = attachDocArr;
                    initBtn(btnFlag);
                } else {
                    Alert(Sepoa.cache.text.get("MESSAGE.1002"));
                }
            });




            if (SCREEN_MODE == 'GW') {
                callFunction('p', 'doGroupBack', []);
            } else {
                callFunction('p', 'doBack', []);
            }
            pageClear();




            if (!formObj.validate()) {
                Alert(Sepoa.cache.text.get('MESSAGE.0002'));
                return;
            }

            if (!gridObj2.validate()) {
                Alert(Sepoa.cache.text.get('MESSAGE.0002'));
                return;
            }

            var formData = Object.assign(formObj.getFormData());            
            //var useNumber = formObj.getValue("SEAL_USE_TYPE");

            //formData.REQ_SEAL_USE_TYPE = formObj.getValue('SEAL_USE_TYPE'); //용도의 값

            $reqSealInfo = formData;

            var attachDocArr = new Array();
            gridObj2.forEachRowA(function(id) {
                var attachDocData = {};
                attachDocData.SD_NUMBER = gridObj2.cells(id, gridObj2.getColIndexById('SD_NUMBER')).getValue();
                attachDocData.SMI_NUMBER = gridObj2.cells(id, gridObj2.getColIndexById('SMI_NUMBER')).getValue();
                attachDocData.COUNT = String(gridObj2.cells(id, gridObj2.getColIndexById('COUNT')).getValue());
                attachDocData.CONTENTS = gridObj2.cells(id, gridObj2.getColIndexById('CONTENTS')).getValue();
                attachDocData.REAL_DOC_CHK = gridObj2.cells(id, gridObj2.getColIndexById('REAL_DOC_CHK')).getValue();

                attachDocArr.push(attachDocData);
            });

            $attachDocumentList = attachDocArr;

            var config = {
                url: window.CONTEXT_NAME + '/SepoaActionController.sux',
                on: {
                    callback: function(res) {
                        if (res.status == "1") {
                            if (callbackObj) { //임시저장이 아닌경우 callbackObj를 인자값으로 받음
                                callbackObj.CALLBACK(callbackObj.CALLBACK_PARMETER);
                            } else {
                                Alert(Sepoa.cache.text.get('MESSAGE.0001'));
                                if (moveFlag == 'Y') { //새로 만든 요청이라면 
                                    linkTo('SLM_200', '/Seal/Document/Request/SealDocumentRequestLayout.sux', 'undefined', Sepoa.cache.text.get('SLM_221.REQUEST_LIST'));
                                    SUX.root.getContentsCell(window).close();
                                }
                            }
                        } else {
                            Alert(res.message);
                        }
                    }
                }
            }

            $reqSealInfo.APP_TYPE = 'J09'; // 증명서 발급 전용

            var serviceData = {
                REQ_SEAL_INFO: $reqSealInfo,
                ATTACH_DOCUMENT_LIST: attachDocArr
            };

            var params = {
                module: "seal" + (Sepoa.config.get('sepoa.seal.process') || "") + ".req",
                action: "doRequestService",
                CONNECTION: "TRANSACTION",
                CURRENT_PRC: "CREATE_CERT",
                SMR_NUMBER: formObj.getValue('SMR_NUMBER'),
                PARAMETER: JSON.stringify(serviceData),
                DEL_ROW2: deleteRows2
            }

            if (callbackObj) { //임시저장이 아닐경우
                sUtils.multipart.send(config, params); //파일 없을 경우
            } else { //임시저장 또는 새로운 요청일 경우 저장 유무를 묻는다.
                Confirm(Sepoa.cache.text.get('SLM_123.MESSAGE009'), function(flag) {
                    if (flag) {
                        sUtils.multipart.send(config, params);
                    }
                });
            }




            var config = {
                url: window.CONTEXT_NAME + '/SepoaActionController.sux',
                on: {
                    callback: function(res) {
                        if (res.status == "1") {
                            Alert(Sepoa.cache.text.get('MESSAGE.0001'));
                            if (Sepoa.request.SMR_NUMBER) {
                                doQuery(Sepoa.request.SMR_NUMBER);
                            } else if (smrStatus == 'T' && moveFlag == 'Y') {
                                linkTo('SLM_200', '/Seal/Document/Request/SealDocumentRequestLayout.sux', 'undefined', Sepoa.cache.text.get('SLM_221.REQUEST_LIST'));
                                SUX.root.getContentsCell(window).close();
                            } else {
                                doBack();
                            }
                        } else {
                            Alert(res.message);
                        }
                    }
                }
            }

            // $reqSealInfo.CONFIRM_STATUS = callbackParams.LEGAL_PRC_TYPE;

            var serviceData = {
                REQ_SEAL_INFO: $reqSealInfo,
                DOCUMENT_LIST: $documentList,
                APP_LINE: params.data.approver,
                APP_INFO: {
                    APP_COMMENT: params.data.comment
                }
            };

            var params = {
                module: "seal" + (Sepoa.config.get('sepoa.seal.process') || "") + ".req",
                action: "doRequestService",
                CONNECTION: "TRANSACTION",
                CURRENT_PRC: "APPROVAL",
                PARAMETER: JSON.stringify(serviceData)
            }

            sUtils.multipart.send(config, params);




            if (!formObj.validate()) {
                Alert(Sepoa.cache.text.get('MESSAGE.0002'));
                return;
            }

            Confirm(Sepoa.cache.text.get('SLM_221.MESSAGE_APPROVAL_REQUEST'), function(flag) {
                if (flag) {
                    doSave({
                        CALLBACK: doSetApproval,
                        CALLBACK_PARMETER: {
                            APPROVAL_PRC_TYPE: "APPROVAL_REQUEST",
                        }
                    });
                }
            });




        	doServiceAjax('sepoa.svc.iams.SepoaIamsService', 'TRANSACTION', 'sendApproval', { 
            	SMR_NUMBER: $reqSealInfo.SMR_NUMBER, APPLY_TYPE: "D"
            }, function(so) {
		    	if (so.status == 1) {
					console.log(so.result[0]);
				    var width = Math.min(SUX.root.innerWidth * 0.7, 1280);
				    var height = Math.min((SUX.root.innerHeight - 100) * 0.9, 800);
					var win = window.open(so.result[0], Sepoa.cache.text.get('SLM_221.APPLINE_SETTING'), "width=" + width + ",height=" + height );
					setTimeout(function run() {
						if(win.closed) {
						    if (Sepoa.request.SMR_NUMBER) {
								doQuery(Sepoa.request.SMR_NUMBER);
						    } else if (smrStatus == 'T' && moveFlag == 'Y') {
								linkTo('SLM_200', '/Seal/Document/Request/SealDocumentRequestLayout.sux', 'undefined', Sepoa.cache.text.get('SLM_211.REQUEST_LIST'));
								SUX.root.getContentsCell(window).close();
						    } else {
								doBack();
						    }
						} else {
							setTimeout(run, 500);
						}
					}, 500);
				} else {
					Alert(so.message);
				}
			});

            /*var params = {};
            //교부서류를 D라고 한다.
            params.data = [{
                SEAL_SORT: 'D',
                APP_LINE_SEQ: '0',
                APP_METHOD: '01',
                APP_USER_ID: Sepoa.info.ID,
                APP_USER_NAME: Sepoa.info.NAME_LOC,
                SELLER_CODE: Sepoa.info.COMPANY_CODE,
                POSITION: Sepoa.info.POSITION,
                DEPARTMENT_NAME: Sepoa.info.DEPARTMENT_NAME_LOC,
                EMPLOYEE_NO: Sepoa.info.EMPLOYEE_NO,
                MANAGE_NO_LIST: manage_no_list
            }];

            var width = Math.min(SUX.root.innerWidth * 0.7, 1280);
            var height = Math.min((SUX.root.innerHeight - 100) * 0.9, 800);
            PopupOpenPost('/UxDefault/ApprovalLine/Popup.sux', params, function(data) {
                var params = {};
                params.data = data;
                params.callbackParams = callbackParams;

                doApprovalProcess(params);
            }, width, height, Sepoa.cache.text.get('SLM_221.APPLINE_SETTING'));
            */





            if (!formObj.validate() || !gridObj.validate()) {
                Alert(Sepoa.cache.text.get('MESSAGE.0002')); //필수입력값을 입력해주세요.
                return;
            } else if (gridObj.getRowsNum() == 0) {
                Alert(Sepoa.cache.text.get('SLM_221.MSG_ADD_SEAL_DOC'));
                return;
            } else if (!validateGrid()) {
                return;
            }

            Confirm(Sepoa.cache.text.get('SLM_221.MESSAGE_REQUEST'), function(flag) {
                if (flag) {
                    doSave({
                        CALLBACK: doManagerProcess,
                        CALLBACK_PARMETER: {
                            LEGAL_PRC_TYPE: "MANAGER_REQUEST"
                        }
                    });
                }
            });




            if (!formObj.validate()) {
                Alert(Sepoa.cache.text.get('MESSAGE.0002'));
                return;
            }

            Confirm(Sepoa.cache.text.get('SLM_221.MESSAGE_REQUEST_CONFIRM'), function(flag) {
                if (flag) {
                    popupReason({
                        title: Sepoa.cache.text.get('SLM_211.CONFIRM_REASON'),
                        callbackFn: doManageAcceptAfterReason,
                        mode: "WRITE"
                    });
                }
            });




            sUtils.popup.modal({
                url: '/UxDefault/Common/WindowForm.sux',
                title: data.title,
                header: true,
                params: {
                    mode: data.mode,
                    form: 'APP_COMMENT',
                    callback: data.callbackFn || function() {}
                }
            })




            doSave({
                CALLBACK: doManagerProcess,
                CALLBACK_PARMETER: {
                    LEGAL_PRC_TYPE: "MANAGER_ACCEPT",
                    ACCEPT_REASON: obj.APP_COMMENT
                }
            });

            return true;




            doSave({
                CALLBACK: doManagerProcess,
                CALLBACK_PARMETER: {
                    LEGAL_PRC_TYPE: "MANAGER_REJECT",
                    ACCEPT_REASON: obj.APP_COMMENT
                }
            });

            return true;




            if (!formObj.validate()) {
                Alert(Sepoa.cache.text.get('MESSAGE.0002'));
                return;
            }

            Confirm(Sepoa.cache.text.get('SLM_221.MESSAGE_REQUEST_REJECT'), function(flag) {
                if (flag) {
                    popupReason({
                        title: Sepoa.cache.text.get('SLM_211.REJECT_REASON'),
                        callbackFn: doManageRejectAfterReason,
                        mode: "REJECT"
                    });
                }
            });




            var config = {
                url: window.CONTEXT_NAME + '/SepoaActionController.sux',
                on: {
                    callback: function(res) {
                        if (res.status == "1") {
                            Alert(Sepoa.cache.text.get('MESSAGE.0001'));
                            if (Sepoa.request.SMR_NUMBER) { //이미 SMR_NUMBER값이 있었다면
                                doQuery(Sepoa.request.SMR_NUMBER);
                            } else if (smrStatus == 'T' && moveFlag == 'Y') { //새로 만든 요청이라면 
                                linkTo('SLM_200', '/Seal/Document/Request/SealDocumentRequestLayout.sux', 'undefined', Sepoa.cache.text.get('SLM_221.REQUEST_LIST'));
                                SUX.root.getContentsCell(window).close();
                            } else {
                                doBack();
                            }
                        } else {
                            Alert(res.message);
                        }
                    }
                }
            }

            var reqSealInfo = $reqSealInfo; //smr_number,폼데이터등의 정보
            reqSealInfo.CONFIRM_STATUS = callbackParams.LEGAL_PRC_TYPE; //임시저장 아닌 다른 버튼 클릭시 버튼마다 지정되어 있는 타입을 가져옴(ex: "MANAGER_REQUEST"(인감담당자에게 승인요청시))
            $reqSealInfo.ACCEPT_REASON = callbackParams.ACCEPT_REASON;

            //$documentList 는 요청시 저장되는 gridObj의 데이터
            var serviceData = {
                REQ_SEAL_INFO: $reqSealInfo,
                DOCUMENT_LIST: $documentList
            };

            var params = {
                module: "seal" + (Sepoa.config.get('sepoa.seal.process') || "") + ".req",
                action: "doRequestService",
                CONNECTION: "TRANSACTION",
                CURRENT_PRC: "MANAGER",
                PARAMETER: JSON.stringify(serviceData)
            }

            sUtils.multipart.send(config, params);




            if (!formObj.validate()) {
                Alert(Sepoa.cache.text.get('MESSAGE.0002'));
                return;
            }

            formObj.setValue('CONFIRM_DATE', sUtils.date.getToday());
            formObj.setValue('CONFIRM_USER_ID', Sepoa.info.ID);
            formObj.setValue('CONFIRM_TIME', sUtils.date.getTime());

            Confirm(Sepoa.cache.text.get('SLM_211.MSG_0030'), function(flag) {
                if (flag) {
                    doSave({
                        CALLBACK: doCompleteProcess,
                        CALLBACK_PARMETER: {
                            COMPLETE_PRC_TYPE: "COMPLETE"
                        }
                    });
                }
            });




            var config = {
                url: window.CONTEXT_NAME + '/SepoaActionController.sux',
                on: {
                    callback: function(res) {
                        if (res.status == "1") {
                            Alert(Sepoa.cache.text.get('MESSAGE.0001'));
                            if (Sepoa.request.SMR_NUMBER) {
                                doQuery(Sepoa.request.SMR_NUMBER);
                            } else if (smrStatus == 'T' && moveFlag == 'Y') {
                                linkTo('SLM_200', '/Seal/Document/Request/SealDocumentRequestLayout.sux', 'undefined', Sepoa.cache.text.get('SLM_221.REQUEST_LIST'));
                                SUX.root.getContentsCell(window).close();
                            } else {
                                doBack();
                            }
                        } else {
                            Alert(res.message);
                        }
                    }
                }
            }

            var serviceData = {
                REQ_SEAL_INFO: $reqSealInfo,
                DOCUMENT_LIST: $documentList
            };

            var params = {
                module: "seal" + (Sepoa.config.get('sepoa.seal.process') || "") + ".req",
                action: "doRequestService",
                CONNECTION: "TRANSACTION",
                CURRENT_PRC: "COMPLETE",
                PARAMETER: JSON.stringify(serviceData)
            }

            sUtils.multipart.send(config, params);




            formObj.clear();
            gridObj.clearAll();
            hideAllButtons();




            return true;




            var maxRowId = dhx4.newId();
            var sdNumber = getDocumentNumber("SD");
            gridObj2.addRow(maxRowId, '', gridObj2.getRowsNum());
            gridObj2.cells(maxRowId, gridObj2.getColIndexById('SMI_SEQ_TEMP')).setValue('temp_' + maxRowId);
            gridObj2.cells(maxRowId, gridObj2.getColIndexById('SD_NUMBER')).setValue(sdNumber);
            gridObj2.showRow(maxRowId);




            var grid_array = gridObj2.getGridChangedRows("SELECTED");
            if (grid_array.length < 1) {
                Alert(Sepoa.cache.text.get('MESSAGE.MSG_1001'));
            } else {
                Confirm(Sepoa.cache.text.get('MESSAGE.1010'), function(result) {
                    if (result) {
                        var smr_seq = null;
                        for (var i in grid_array) {
                            deleteRows2.push(gridObj2.cells(grid_array[i], gridObj2.getColIndexById('SD_NUMBER')).getValue());
                            gridObj2.deleteRow(grid_array[i]);
                        }
                    }
                });
            }




            var header = this.getColumnId(cInd);
            selectedGridId = id;

            if (header == "ATTACH_IMG") {
                var confirm_val = false;

                if (gridObj2.cells(id, gridObj2.getColIndexById("REAL_DOC_CHK")).getValue() == '1' ||
                    (gridObj2.cells(id, gridObj2.getColIndexById("ATTACH_SEQ")).getValue() == '' &&
                        Sepoa.info.CTRL_CODE.indexOf('ATTACH_CONFIRM') < 0)) {
                    return false;
                } else if (Sepoa.info.CTRL_CODE.indexOf('ATTACH_CONFIRM') > -1
                    //&& gridObj2.cells(id, gridObj2.getColIndexById("ATTACH_SEQ")).getValue() == ''
                ) {
                    confirm_val = true;
                }

                var attachNo = gridObj2.cells(id, gridObj2.getColIndexById("ATTACH_NO")).getValue();
                callVaultPopup(attachNo, confirm_val);
            }




            var header = gridObj2.getColumnId(cInd);
            var chk_disable = gridObj2.cells(rId, gridObj2.getColIndexById('REAL_DOC_CHK')).isDisabled();

            if (stage == 0 && header == "REAL_DOC_CHK" && chk_disable == true) {
                return false;
            } else if (stage == 2 && header == "SMI_NUMBER") {
                searchSRAD(rId, nValue);
            }

            return true;




            //교부서류 그리드(gridObj2) 다시 set하는 코드 넣기




            doServiceAjax('sepoa.svc.seal.SepoaReqSealService', 'CONNECTION', 'doCorpDocInfo', {
                SMI_NUMBER: smi_no
            }, function(so) {
                if (so.status == 1) {
                    var sf = new SepoaFormater(so.result[0]);
                    var sfList = sf.getArrayMap();
                    var r_flag;
                    var e_flag;

                    if (sf.getRowCount() > 0) {
                        var ListResult = sfList[0];
                        r_flag = ListResult.REAL_DOC_FLAG;
                        e_flag = ListResult.ELEC_DOC_FLAG;

                        if (r_flag == '1' && e_flag != '1') { //실물만
                            gridObj2.cells(rId, gridObj2.getColIndexById('REAL_DOC_CHK')).setValue('1');
                            gridObj2.cells(rId, gridObj2.getColIndexById('REAL_DOC_CHK')).setDisabled(true);
                        } else if ((r_flag == '1' && e_flag == '1')) { //둘다
                            gridObj2.cells(rId, gridObj2.getColIndexById('REAL_DOC_CHK')).setDisabled(false);
                        } else if ((r_flag != '1' && e_flag == '1')) { //전자만
                            gridObj2.cells(rId, gridObj2.getColIndexById('REAL_DOC_CHK')).setValue('0');
                            gridObj2.cells(rId, gridObj2.getColIndexById('REAL_DOC_CHK')).setDisabled(true);
                        } else { //빈값
                            gridObj2.cells(rId, gridObj2.getColIndexById('REAL_DOC_CHK')).setValue('0');
                            gridObj2.cells(rId, gridObj2.getColIndexById('REAL_DOC_CHK')).setDisabled(false);
                        }
                    }
                } else {
                    Alert(Sepoa.cache.text.get("MESSAGE.MISSING_DOC"));
                }
            });




            var type = 'TODO_DOC';
            var mode = confirm_val == true ? '' : 'VI';
            vaultPopup({
                attach_key: attachNo,
                type: type,
                mode: mode,
                callback: attach_callback
            });




            var result;

            doServiceAjax('sepoa.svc.seal.SepoaReqSealService', 'CONNECTION', 'doSearchFMFI', {
                DOC_NUMBER: doc_number
            }, function(so) {
                if (so.status == 1) {
                    result = so.result[0];
                } else {
                    Alert(Sepoa.cache.text.get("SLM_221.MISSING_FMFI"));
                }
            }, false);

            return result;
